// Verifies DevPilot's HMAC signature, then builds a signed callback (ARCHITECTURE §8.1).
// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto, N8N_BLOCK_ENV_ACCESS_IN_NODE=false and DEVPILOT_WEBHOOK_SECRET in n8n's environment.
const crypto = require('crypto');
const secret = $env.DEVPILOT_WEBHOOK_SECRET;
if (!secret) throw new Error('DEVPILOT_WEBHOOK_SECRET is not set in n8n');
// DevPilot signs JSON with sorted keys and no spaces; rebuild exactly that from the parsed body.
const canonical = (v) => Array.isArray(v) ? '[' + v.map(canonical).join(',') + ']'
  : (v !== null && typeof v === 'object') ? '{' + Object.keys(v).sort().map((k) => JSON.stringify(k) + ':' + canonical(v[k])).join(',') + '}'
  : JSON.stringify(v);
const hmac = (ts, text) => 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.' + text).digest('hex');
const item = $input.first().json;
const headers = item.headers || {};
const ts = headers['x-devpilot-timestamp'];
const given = String(headers['x-devpilot-signature'] || '');
const expected = ts ? hmac(ts, canonical(item.body)) : '';
const fresh = ts && Math.abs(Date.now() / 1000 - Number(ts)) <= 300;
if (!fresh || given.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(given), Buffer.from(expected))) {
  throw new Error('DevPilot signature rejected');
}
const sent = item.body;
if (!sent.callback_url) throw new Error('DevPilot sent no callback_url: set N8N_CALLBACK_URL');
const reply = canonical({
  trigger_id: sent.trigger_id, project_id: sent.project_id, run_id: sent.run_id,
  status: 'success', execution_id: String($execution.id), result: { echo: sent.inputs.text },
});
const now = String(Math.floor(Date.now() / 1000));
return [{ json: { callback_url: sent.callback_url, timestamp: now, signature: hmac(now, reply), body: reply } }];
